    function isFarsi(str) {
        var pattern = /^[a-zA-Z]*$/;
        var pattern2 = /^[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]*$/
        for(var i=0;i<=str.length;i++){
            if(str.charCodeAt(i) <= 255) {
                if(str.charAt(i).match(pattern)) {
                    return false;
                }else{
                    if(str.match(pattern2) || str.length ==1 || $.isNumeric(str)){
                        return false;
                    }
                }
            }
        }
        if(str.length == 0){
            return false;
        }
        return true;
    }
    function farsiCount(number){
        if(number <= 70){
            return 1;
        }else if(number >= 71 && number <=134){
            return 2;
        }else{
            number = number - 134;
            var temp = Math.ceil((number/67));
            return (temp+2);
        }
    }
    function engCount(number){
        if(number <= 160){
            return 1;
        }else if(number >= 161 && number <=306){
            return 2;
        }else{
            number = number - 306;
            var temp = Math.ceil((number/153));
            return (temp+2);
        }
    }
    function counterSMStext(text,langbox,characterbox,smscount){
        characterbox.text(text.length);
        if(isFarsi(text)){
            langbox.text("فارسی");
            smscount.text(farsiCount(text.length));
        }else{
            langbox.text("انگلیسی");
            smscount.text(engCount(text.length));
        }
    }
    function countSMS(textbox,langbox,characterbox,smscount) {
        counterSMStext(textbox.val(),langbox,characterbox,smscount);
        textbox.on('keyup',function(){
            counterSMStext(textbox.val(),langbox,characterbox,smscount);
        });
    }
